namespace Nightwave.Core.Streaming;

/// <summary>
/// Audio frames that decode to silence, for bridging an outage. Coded frames, not samples: nothing
/// is encoded here. An MPEG audio frame with all bit allocations at zero is silence by definition.
/// AC-3 has no such shortcut, so the two channel layouts of broadcast are kept as frames of
/// digital silence; they are padded to the bit rate of the stream and their checksums worked out.
/// </summary>
public static class SilentAudio
{
    /// <summary>The samples of one frame of MPEG audio Layer II.</summary>
    public const int MpegSamples = 1152;

    /// <summary>The samples of one AC-3 frame.</summary>
    public const int Ac3Samples = 1536;

    private const uint CrcPolynomial = 0x18005;

    private const string Ac3Stereo = "";

    private const string Ac3Surround = "";

    private static readonly int[] Ac3Rates = [32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384, 448, 512, 576, 640];

    /// <summary>A silent frame with the format of this frame header, or null where there is none to be had.</summary>
    public static byte[]? MpegFrame(ReadOnlySpan<byte> header)
    {
        if (header.Length < 4 || header[0] != 0xFF || (header[1] & 0xFE) != 0xFC)
        {
            return null;
        }

        int[] rates = [0, 32, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 384];
        int[] samples = [44100, 48000, 32000];
        var rate = header[2] >> 4;
        var sample = (header[2] >> 2) & 3;

        if (rate is 0 or 15 || sample == 3)
        {
            return null;
        }

        var frame = new byte[144 * rates[rate] * 1000 / samples[sample]];

        frame[0] = 0xFF;
        frame[1] = 0xFD;
        frame[2] = (byte)(header[2] & 0xFC);
        frame[3] = header[3];

        return frame;
    }

    /// <summary>
    /// A silent frame with the format of this AC-3 frame header, or null for a sample rate other
    /// than 48 kHz, a channel layout other than 2.0 and 5.1, or a rate below what the frame needs.
    /// </summary>
    public static byte[]? Ac3Frame(ReadOnlySpan<byte> header)
    {
        if (header.Length < 8 || header[0] != 0x0B || header[1] != 0x77 || (header[4] >> 6) != 0 || (header[5] >> 3) > 8)
        {
            return null;
        }

        var size = (header[4] & 0x3F) >> 1;

        if (size >= Ac3Rates.Length)
        {
            return null;
        }

        var template = (header[6] >> 5) switch
        {
            2 => Ac3Stereo,
            7 => Ac3Surround,
            _ => null,
        };

        if (template is null)
        {
            return null;
        }

        var length = Ac3Rates[size] * 4;
        var body = Convert.FromHexString(template);

        if (body.Length + 3 > length)
        {
            return null;
        }

        var frame = new byte[length];

        body.CopyTo(frame, 0);
        frame[4] = (byte)(size << 1);

        Seal(frame);

        return frame;
    }

    /// <summary>Writes the two checksums of an AC-3 frame (A/52, 7.10.1).</summary>
    private static void Seal(byte[] frame)
    {
        var fiveEighths = ((frame.Length >> 2) + (frame.Length >> 4)) << 1;

        frame[2] = 0;
        frame[3] = 0;

        var first = Crc(frame.AsSpan(4, fiveEighths - 4));
        var inverse = Power(CrcPolynomial >> 1, (uint)((8 * fiveEighths) - 16));
        var value = Multiply(inverse, first);

        frame[2] = (byte)(value >> 8);
        frame[3] = (byte)value;

        var second = Crc(frame.AsSpan(fiveEighths, frame.Length - fiveEighths - 2));

        frame[^2] = (byte)(second >> 8);
        frame[^1] = (byte)second;
    }

    private static uint Crc(ReadOnlySpan<byte> data)
    {
        uint crc = 0;

        foreach (var value in data)
        {
            crc ^= (uint)value << 8;

            for (var bit = 0; bit < 8; bit++)
            {
                crc = (crc & 0x8000) != 0 ? ((crc << 1) ^ CrcPolynomial) & 0xFFFF : (crc << 1) & 0xFFFF;
            }
        }

        return crc;
    }

    private static uint Multiply(uint a, uint b)
    {
        uint product = 0;

        while (a != 0)
        {
            if ((a & 1) != 0)
            {
                product ^= b;
            }

            a >>= 1;
            b <<= 1;

            if ((b & 0x10000) != 0)
            {
                b ^= CrcPolynomial;
            }
        }

        return product;
    }

    private static uint Power(uint value, uint exponent)
    {
        uint result = 1;

        while (exponent != 0)
        {
            if ((exponent & 1) != 0)
            {
                result = Multiply(result, value);
            }

            value = Multiply(value, value);
            exponent >>= 1;
        }

        return result;
    }
}
